// Clear any previous run data
const staticData = $getWorkflowStaticData('global');
staticData.tierResults = [];

return $input.all();

var allItems = $input.all();
var convexTiers = allItems.map(function(item) { return item.json; });

var TEST_MODE = true;
var TEST_LEADS_PER_TIER = 5;

// === FILTER OVERRIDES ===
// Convex tier_configs is source of truth (deployed 2026-05-02).
var FILTER_OVERRIDES = {};

// === ZIP CODE OVERRIDES ===
var ZIP_OVERRIDES = {};

if (!convexTiers || convexTiers.length === 0) {
  console.log('WARNING: No tier configs from Convex');
  return [{ json: { tier: 'tier_1_premium_suburbs', name: 'Fallback', leadsTarget: TEST_LEADS_PER_TIER, listingType: 'High_ARV', zipCodes: ['44136'], filters: { price_min: 200000, price_max: 800000, property_types: ['Single Family', 'Duplex'], distress_pre_foreclosure: true, distress_tax_default: true, distress_has_lien: true }, importDate: new Date().toISOString().split('T')[0], importId: 'import_fallback_' + Date.now() } }];
}

var importDate = new Date().toISOString().split('T')[0];
var importId = 'import_' + importDate + '_' + Date.now();
var batchDataTiers = convexTiers.filter(function(tier) { return tier.tier !== 'cleveland_311'; });

// === EXPIRED TIER MERGING ===
var expiredTiers = [];
var nonExpiredTiers = [];
for (var e = 0; e < batchDataTiers.length; e++) {
  if (batchDataTiers[e].listing_type && batchDataTiers[e].listing_type.indexOf('Expired') === 0) {
    expiredTiers.push(batchDataTiers[e]);
  } else {
    nonExpiredTiers.push(batchDataTiers[e]);
  }
}

if (expiredTiers.length > 0) {
  var totalExpiredTarget = 0;
  var expiredTierConfigs = [];
  for (var ei = 0; ei < expiredTiers.length; ei++) {
    var et = expiredTiers[ei];
    var etTarget = TEST_MODE ? TEST_LEADS_PER_TIER : et.leads_target;
    totalExpiredTarget += etTarget;
    expiredTierConfigs.push({
      tier: et.tier,
      name: et.name,
      listingType: et.listing_type,
      leadsTarget: etTarget
    });
  }
  nonExpiredTiers.push({
    tier: 'expired_combined',
    name: 'All Expired Listings',
    leads_target: totalExpiredTarget,
    listing_type: 'Expired',
    zip_codes: expiredTiers[0].zip_codes,
    filters: expiredTiers[0].filters,
    isExpired: true,
    expiredTierConfigs: expiredTierConfigs
  });
  console.log('EXPIRED: Merged ' + expiredTiers.length + ' tiers into 1 combined entry (target: ' + totalExpiredTarget + ' leads)');
}
batchDataTiers = nonExpiredTiers;

console.log((TEST_MODE ? 'TEST' : 'PROD') + ' MODE: ' + batchDataTiers.length + ' tiers x ' + (TEST_MODE ? TEST_LEADS_PER_TIER : 'target') + ' leads');

return batchDataTiers.map(function(tier) {
  var filters = {};
  var keys = Object.keys(tier.filters || {});
  for (var i = 0; i < keys.length; i++) filters[keys[i]] = tier.filters[keys[i]];

  var overrides = FILTER_OVERRIDES[tier.tier];
  if (overrides) {
    var oKeys = Object.keys(overrides);
    for (var j = 0; j < oKeys.length; j++) {
      var key = oKeys[j];
      var value = overrides[key];
      if (value === undefined) {
        delete filters[key];
        console.log('OVERRIDE ' + tier.tier + ': REMOVED ' + key);
      } else {
        filters[key] = value;
        console.log('OVERRIDE ' + tier.tier + ': ' + key + ' -> ' + value);
      }
    }
  }

  var zipCodes = tier.zip_codes;
  if (ZIP_OVERRIDES[tier.tier]) {
    zipCodes = ZIP_OVERRIDES[tier.tier];
    console.log('ZIP OVERRIDE ' + tier.tier + ': ' + (tier.zip_codes ? tier.zip_codes.length : 0) + ' -> ' + zipCodes.length + ' zips');
  }

  return {
    json: {
      tier: tier.tier,
      name: tier.name,
      leadsTarget: tier.isExpired ? tier.leads_target : (TEST_MODE ? TEST_LEADS_PER_TIER : tier.leads_target),
      listingType: tier.listing_type,
      zipCodes: zipCodes,
      filters: filters,
      importDate: importDate,
      importId: importId,
      isExpired: tier.isExpired || false,
      expiredTierConfigs: tier.expiredTierConfigs || null
    }
  };
});

var tier = $input.first().json;
var filters = tier.filters || {};

// === EXPIRED LISTING DETECTION ===
var isExpired = tier.isExpired || (tier.listingType && tier.listingType.indexOf('Expired') === 0);

var orQuickLists = [];
var quickLists = [];

if (isExpired) {
  // Expired listings: pull from expired/failed/canceled MLS lists
  orQuickLists = ['expired-listing', 'failed-listing', 'canceled-listing'];
  // Still apply corporate/trust exclusion filters
  if (filters.exclude_corporate) quickLists.push('not-corporate-owned');
  if (filters.exclude_trust) quickLists.push('not-trust-owned');
} else {
  // === EXISTING DISTRESS LOGIC (UNCHANGED) ===
  if (filters.distress_pre_foreclosure) orQuickLists.push('preforeclosure');
  if (filters.distress_tax_default) orQuickLists.push('tax-default');
  if (filters.distress_has_lien) orQuickLists.push('involuntary-lien');
  if (filters.vacant) orQuickLists.push('vacant');
  if (filters.high_equity) orQuickLists.push('high-equity');
  if (filters.senior_owner) orQuickLists.push('senior-owner');
  if (filters.tired_landlord) orQuickLists.push('tired-landlord');
  if (filters.inherited) orQuickLists.push('inherited');
  if (filters.absentee_owner) orQuickLists.push('absentee-owner');

  if (filters.exclude_corporate) quickLists.push('not-corporate-owned');
  if (filters.exclude_trust) quickLists.push('not-trust-owned');

  if (filters.occupancy && filters.occupancy !== 'any') {
    if (filters.occupancy === 'absentee') {
      quickLists.push('absentee-owner');
    } else if (filters.occupancy === 'out_of_state_absentee') {
      quickLists.push('out-of-state-absentee-owner');
    }
  }

  if (filters.distress_operator === 'AND') {
    var distressItems = ['preforeclosure', 'tax-default', 'involuntary-lien'];
    distressItems.forEach(function(item) {
      var idx = orQuickLists.indexOf(item);
      if (idx !== -1) {
        orQuickLists.splice(idx, 1);
        quickLists.push(item);
      }
    });
  }
}

var propertyTypes = filters.property_types && filters.property_types.length > 0 ? filters.property_types : ['Single Family', 'Duplex', 'Triplex', 'Quadplex'];
var priceMin = filters.price_min || 80000;
var priceMax = filters.price_max || 800000;
var sessionId = 'session_' + tier.importId + '_' + tier.tier;

var requestBody = {
  searchCriteria: {
    address: { zip: { inList: tier.zipCodes } },
    general: { propertyTypeDetail: { inList: propertyTypes } },
    estimatedValue: { min: priceMin, max: priceMax }
  },
  options: { skip: 0, take: tier.leadsTarget, sessionId: sessionId }
};

if (orQuickLists.length > 0) requestBody.searchCriteria.orQuickLists = orQuickLists;
if (quickLists.length > 0) requestBody.searchCriteria.quickLists = quickLists;
if (filters.equity_min_pct) requestBody.searchCriteria.equity = { min: filters.equity_min_pct };
if (filters.years_owned_min) requestBody.searchCriteria.yearsOwned = { min: filters.years_owned_min };
if (filters.lot_size_min_acres || filters.lot_size_max_acres) {
  requestBody.searchCriteria.lot = {};
  if (filters.lot_size_min_acres) requestBody.searchCriteria.lot.lotSizeAcresMin = filters.lot_size_min_acres;
  if (filters.lot_size_max_acres) requestBody.searchCriteria.lot.lotSizeAcresMax = filters.lot_size_max_acres;
}

console.log('=== BUILD BATCHDATA REQUEST ===');
console.log('Tier: ' + tier.tier + ' | Props: ' + JSON.stringify(propertyTypes));
console.log('quickLists: ' + JSON.stringify(quickLists));
console.log('orQuickLists: ' + JSON.stringify(orQuickLists));
if (isExpired) console.log('MODE: EXPIRED LISTING (1 API call for all expired tiers)');

return [{ json: {
  tier: tier.tier, tierName: tier.name, listingType: tier.listingType,
  leadsTarget: tier.leadsTarget, importDate: tier.importDate, importId: tier.importId,
  sessionId: sessionId, requestBody: requestBody, filters: filters,
  isExpired: isExpired, expiredTierConfigs: tier.expiredTierConfigs || null
} }];

// Get BatchData results and Convex duplicate check results
const batchDataResponse = $('Call BatchData API').item.json;
const batchDataResults = (batchDataResponse.results && batchDataResponse.results.properties) || [];
const duplicateCheck = $input.item.json;

// Get tier info from the Build BatchData Request node
const tierInfo = $('Build BatchData Request').item.json;

// CRITICAL: Track original count for pagination (before any filtering)
const originalCount = batchDataResults.length;

// Get the new address indices from Convex response
const convexValue = duplicateCheck.value || duplicateCheck;
const newAddressIndices = new Set(
  (convexValue.newAddresses || []).map(function(a) { return a.index; })
);

// ========== LLC/CORPORATE FILTER ==========
const corporatePatterns = /\b(LLC|L\.?L\.?C|INC|INCORPORATED|CORP|CORPORATION|LP|L\.?P|LTD|LIMITED|TRUST|REVOCABLE|IRREVOCABLE|ESTATE|PARTNERSHIP|HOLDING|HOLDINGS|PROPERTIES|INVESTMENTS|MANAGEMENT|REALTY|CAPITAL|VENTURES|FUND|GROUP|ASSOCIATES|PARTNERS|COMPANY|CO\.|BANK|DAO|ASSOC|ENTERPRISES|DEVELOPMENT|RENTALS|ASSET|ASSETS|EQUITY|FINANCIAL|SERVICES|SOLUTIONS|ACQUISITION|ACQUISITIONS)\b/i;

let llcSkipped = 0;
let llcSkippedNames = [];

// Filter to only include new (non-duplicate) AND non-LLC properties
const newProperties = batchDataResults.filter(function(prop, index) {
  if (!newAddressIndices.has(index)) {
    return false;
  }

  const owner = prop.owner || {};
  const ownerNames = owner.names || [];
  const ownerName = ownerNames[0]?.full || ownerNames[0]?.first + ' ' + ownerNames[0]?.last || owner.fullName || '';

  if (corporatePatterns.test(ownerName)) {
    llcSkipped++;
    llcSkippedNames.push(ownerName.substring(0, 50));
    console.log(`SKIPPING LLC (saves $0.02): ${ownerName}`);
    return false;
  }

  return true;
});

const duplicatesRemoved = batchDataResults.length - newAddressIndices.size;
const savedFromDuplicates = duplicatesRemoved * 0.02;
const savedFromLLC = llcSkipped * 0.02;
const totalSaved = savedFromDuplicates + savedFromLLC;

console.log(`Filter stats: ${batchDataResults.length} total -> ${newAddressIndices.size} after dedup -> ${newProperties.length} after LLC filter`);
console.log(`Cost saved: $${savedFromDuplicates.toFixed(2)} (duplicates) + $${savedFromLLC.toFixed(2)} (LLC) = $${totalSaved.toFixed(2)}`);

return [{
  json: {
    results: { properties: newProperties },
    tierInfo: tierInfo,
    deduplicationStats: {
      originalCount: originalCount,  // CRITICAL for pagination
      afterDeduplication: newAddressIndices.size,
      afterLLCFilter: newProperties.length,
      duplicatesRemoved: duplicatesRemoved,
      llcSkipped: llcSkipped,
      llcSkippedNames: llcSkippedNames.slice(0, 10),
      savedSkipTraceCost: '$' + totalSaved.toFixed(2)
    }
  }
}];

// Build JSON data for Tracerfy batch upload
// FIX (Mar 14): Swap addresses — send MAILING address as primary
// FIX (Mar 16): 3-Layer address quality filter
// FIX (Mar 17): Expired listing support — date splitting for E1/E2/E3 tiers
// FIX (Mar 19): Layer 4 (Commercial/Suite) + Layer 5 (Invalid Address) filters
const inputData = $input.first().json;
const tierInfo = inputData.tierInfo || $('Build BatchData Request').first().json;
const properties = (inputData.results && inputData.results.properties) || [];
const deduplicationStats = inputData.deduplicationStats || {};

const tierFilters = tierInfo.filters || $('Build BatchData Request').first().json.filters || {};

console.log('=== DISTRESS SCORE CALCULATION ===');
console.log('Tier:', tierInfo.tier);
console.log('Filters:', JSON.stringify(tierFilters));

const originalBatchDataCount = deduplicationStats.originalCount || properties.length;

if (properties.length === 0) {
  return [{ json: { 
    hasLeads: false, 
    tier: tierInfo.tier, 
    tierName: tierInfo.tierName, 
    listingType: tierInfo.listingType, 
    importId: tierInfo.importId, 
    importDate: tierInfo.importDate, 
    leadsCount: 0, 
    originalBatchDataCount: originalBatchDataCount,
    jsonData: null, 
    leadData: [] 
  } }];
}

const jsonRecords = [];
const leadData = [];

// Build distress indicators from tier filters
const tierDistressIndicators = [];
let tierDistressScore = 0;

if (tierFilters.distress_pre_foreclosure) { tierDistressIndicators.push('pre_foreclosure'); tierDistressScore += 30; }
if (tierFilters.distress_tax_default) { tierDistressIndicators.push('tax_delinquent'); tierDistressScore += 25; }
if (tierFilters.vacant) { tierDistressIndicators.push('vacant'); tierDistressScore += 15; }
if (tierFilters.distress_has_lien) { tierDistressIndicators.push('has_lien'); tierDistressScore += 20; }
if (tierFilters.high_equity) { tierDistressIndicators.push('high_equity'); tierDistressScore += 5; }

// EXPIRED LISTING scoring
if (tierInfo.isExpired || (tierInfo.listingType && tierInfo.listingType.indexOf('Expired') === 0)) {
  tierDistressIndicators.push('expired_listing');
  tierDistressScore += 20;
}

// ABSENTEE OWNER LOGIC
const isAbsentee = tierFilters.occupancy === 'absentee' || tierFilters.occupancy === 'out_of_state_absentee';
const isOutOfState = tierFilters.occupancy === 'out_of_state_absentee';

if (isAbsentee) { tierDistressIndicators.push('absentee'); tierDistressScore += 10; }
if (isOutOfState) { tierDistressIndicators.push('out_of_state'); tierDistressScore += 15; }

console.log('Tier ' + tierInfo.tier + ': absenteeOwner=' + isAbsentee + ', outOfState=' + isOutOfState);
console.log('Tier distress indicators:', tierDistressIndicators, 'Score:', tierDistressScore);

// === COUNTERS ===
let invalidAddressCount = 0;
let emptyAddressCount = 0;
let noMailingCount = 0;
let noMailingZipCount = 0;
let poBoxCount = 0;
let commercialCount = 0;
let batchdataInvalidCount = 0;
let mailSameAsPropCount = 0;

const poBoxPattern = /^\s*P\.?\s*O\.?\s*BOX\b/i;
const commercialPattern = /\b(Ste|Suite|Floor|Fl|Unit|Dept|Bldg|Rm|Room|Ofc|Office|Attn|C\/O)\b/i;
const addressQualityLog = [];

properties.forEach((prop, index) => {
  const addr = prop.address || {};
  const owner = prop.owner || {};
  const ownerNames = owner.names || [];

  const streetAddress = addr.street || addr.full || addr.line1 || '';
  const cleanAddress = streetAddress.trim();

  if (!cleanAddress || cleanAddress.length < 3) {
    emptyAddressCount++;
    console.log('SKIP [' + index + ']: Empty/invalid property address');
    return;
  }

  const propCity = (addr.city || '').trim();
  const propState = (addr.state || 'OH').trim().toUpperCase();
  const propZip = (addr.zip || '').trim();

  if (!propCity || propCity.length < 2) {
    invalidAddressCount++;
    console.log('SKIP [' + index + ']: Invalid city - ' + cleanAddress);
    return;
  }

  if (!propState || propState.length !== 2) {
    invalidAddressCount++;
    console.log('SKIP [' + index + ']: Invalid state - ' + cleanAddress);
    return;
  }

  let firstName = ownerNames[0]?.first || '';
  let lastName = ownerNames[0]?.last || '';

  if (!firstName && !lastName) {
    const fullName = ownerNames[0]?.full || owner.fullName || '';
    const parts = fullName.trim().split(/\s+/);
    firstName = parts[0] || '';
    lastName = parts.slice(1).join(' ') || '';
  }

  const ownerLabel = (firstName + ' ' + lastName).trim() || 'UNKNOWN';

  const mailAddr = owner.mailingAddress || {};
  const hasMailingAddress = !!(mailAddr.street || mailAddr.full || mailAddr.line1);
  const mailStreet = (mailAddr.street || mailAddr.full || mailAddr.line1 || '').trim();
  const mailCity = (mailAddr.city || '').trim();
  const mailState = (mailAddr.state || '').trim().toUpperCase();
  const mailZip = (mailAddr.zip || '').trim();

  if (isAbsentee && !hasMailingAddress) {
    noMailingCount++;
    addressQualityLog.push({ i: index, owner: ownerLabel, reason: 'no_mailing_addr', prop: cleanAddress });
    return;
  }

  if (isAbsentee && mailStreet.length < 3) {
    noMailingCount++;
    addressQualityLog.push({ i: index, owner: ownerLabel, reason: 'empty_mail_street', mail: mailStreet });
    return;
  }

  if (isAbsentee && !mailZip) {
    noMailingZipCount++;
    addressQualityLog.push({ i: index, owner: ownerLabel, reason: 'no_mail_zip', mail: mailStreet + ', ' + mailCity + ', ' + mailState });
    return;
  }

  if (isAbsentee && poBoxPattern.test(mailStreet)) {
    poBoxCount++;
    addressQualityLog.push({ i: index, owner: ownerLabel, reason: 'po_box', mail: mailStreet });
    return;
  }

  // Layer 4: Commercial/Suite address filter
  if (isAbsentee && commercialPattern.test(mailStreet)) {
    commercialCount++;
    console.log('SKIP [' + index + ']: Commercial mailing address (saves $0.02) - ' + mailStreet + ' (' + ownerLabel + ')');
    addressQualityLog.push({ i: index, owner: ownerLabel, reason: 'commercial_address', mail: mailStreet });
    return;
  }

  // Layer 5: BatchData addressValidity filter
  var mailValidity = mailAddr.addressValidity || (prop.mailingAddress && prop.mailingAddress.addressValidity) || '';
  if (isAbsentee && mailValidity && mailValidity.toLowerCase() === 'invalid') {
    batchdataInvalidCount++;
    console.log('SKIP [' + index + ']: Invalid mailing address per BatchData (saves $0.02) - ' + mailStreet + ' (' + ownerLabel + ')');
    addressQualityLog.push({ i: index, owner: ownerLabel, reason: 'invalid_address', mail: mailStreet });
    return;
  }

  const mailNorm = (mailStreet + mailCity + mailState).toLowerCase().replace(/[^a-z0-9]/g, '');
  const propNorm = (cleanAddress + propCity + propState).toLowerCase().replace(/[^a-z0-9]/g, '');
  const isSameAddress = isAbsentee && mailNorm === propNorm;
  if (isSameAddress) {
    mailSameAsPropCount++;
    addressQualityLog.push({ i: index, owner: ownerLabel, reason: 'mail_equals_prop', addr: mailStreet });
  }

  if (isAbsentee && hasMailingAddress) {
    jsonRecords.push({
      address: mailStreet,
      city: mailCity || propCity,
      state: mailState || propState,
      zip: mailZip,
      first_name: firstName,
      last_name: lastName,
      mail_address: cleanAddress,
      mail_city: propCity,
      mail_state: propState,
      mail_zip: propZip
    });
  } else {
    jsonRecords.push({
      address: cleanAddress,
      city: propCity,
      state: propState,
      zip: propZip,
      first_name: firstName,
      last_name: lastName,
      mail_address: '',
      mail_city: '',
      mail_state: '',
      mail_zip: ''
    });
  }

  const qualityGrade = isSameAddress ? 'C' : (mailCity && mailState && mailZip ? 'A' : 'B');
  addressQualityLog.push({ i: index, owner: ownerLabel, reason: 'uploaded', grade: qualityGrade, mail: isAbsentee ? (mailStreet + ', ' + mailCity + ', ' + mailState + ' ' + mailZip) : 'N/A (owner-occupied)' });

  const { source: _, ...propWithoutSource } = prop;

  leadData.push({
    index: jsonRecords.length - 1,
    address: cleanAddress,
    city: propCity,
    state: propState,
    zip: propZip,
    ownerName: ownerLabel,
    propertyData: {
      ...propWithoutSource,
      distressIndicators: tierDistressIndicators,
      distressScore: tierDistressScore,
      primaryDistress: tierDistressIndicators[0] || 'general',
      absenteeOwner: isAbsentee,
      outOfState: isOutOfState,
      listingExpiredDate: (prop.listing || {}).failedListingDate || null,
      listingPrice: (prop.listing || {}).price || (prop.listing || {}).listPrice || null,
      daysOnMarket: (prop.listing || {}).daysOnMarket || null,
      campaignType: tierInfo.isExpired ? 'expired' : 'distressed',
      tierFilters: {
        occupancy: tierFilters.occupancy,
        vacant: tierFilters.vacant,
        distress_pre_foreclosure: tierFilters.distress_pre_foreclosure,
        distress_tax_default: tierFilters.distress_tax_default,
        distress_has_lien: tierFilters.distress_has_lien
      }
    }
  });
});

const validLeadCount = jsonRecords.length;

// === ADDRESS QUALITY REPORT ===
const totalFiltered = emptyAddressCount + invalidAddressCount + noMailingCount + noMailingZipCount + poBoxCount + commercialCount + batchdataInvalidCount;
const creditsSaved = totalFiltered * 0.02;
const gradeA = addressQualityLog.filter(function(r) { return r.grade === 'A'; }).length;
const gradeB = addressQualityLog.filter(function(r) { return r.grade === 'B'; }).length;
const gradeC = addressQualityLog.filter(function(r) { return r.grade === 'C'; }).length;

console.log('=== ADDRESS QUALITY REPORT ===');
console.log('Tier: ' + tierInfo.tier);
console.log('Total records: ' + properties.length);
console.log('Filtered out: ' + totalFiltered + ' (saves $' + creditsSaved.toFixed(2) + ')');
console.log('  - Empty property addr: ' + emptyAddressCount);
console.log('  - Invalid city/state: ' + invalidAddressCount);
console.log('  - No mailing address: ' + noMailingCount);
console.log('  - No mailing ZIP:     ' + noMailingZipCount);
console.log('  - PO Box address:     ' + poBoxCount);
console.log('  - Commercial/Suite:   ' + commercialCount + ' [NEW Layer 4]');
console.log('  - BatchData Invalid:  ' + batchdataInvalidCount + ' [NEW Layer 5]');
console.log('Uploaded: ' + validLeadCount);
console.log('  - Grade A: ' + gradeA + ' | Grade B: ' + gradeB + ' | Grade C: ' + gradeC);
if (addressQualityLog.length > 0 && addressQualityLog.length <= 20) {
  console.log('Per-record detail:');
  addressQualityLog.forEach(function(r) { console.log('  [' + r.i + '] ' + r.owner + ' -> ' + r.reason + (r.grade ? ' (' + r.grade + ')' : '') + (r.mail ? ' | ' + r.mail : '')); });
}

if (validLeadCount === 0) {
  return [{ json: { 
    hasLeads: false, 
    tier: tierInfo.tier, 
    tierName: tierInfo.tierName, 
    listingType: tierInfo.listingType, 
    importId: tierInfo.importId, 
    importDate: tierInfo.importDate, 
    leadsCount: 0, 
    originalBatchDataCount: originalBatchDataCount,
    jsonData: null, 
    leadData: [],
    validationStats: {
      totalRecords: properties.length,
      emptyAddresses: emptyAddressCount,
      invalidCityState: invalidAddressCount,
      noMailingAddress: noMailingCount,
      noMailingZip: noMailingZipCount,
      poBoxFiltered: poBoxCount,
      commercialFiltered: commercialCount,
      batchdataInvalid: batchdataInvalidCount,
      validRecords: 0,
      creditsSaved: creditsSaved
    }
  } }];
}

// === EXPIRED TIER DATE SPLIT ===
if (tierInfo.isExpired && tierInfo.expiredTierConfigs) {
  const now = new Date();
  const tierDateRanges = [
    { tier: 'expired_hot_0_90', listingType: 'Expired_Hot', name: 'Hot Expireds (0-90 Days)', minDays: 0, maxDays: 90 },
    { tier: 'expired_warm_91_365', listingType: 'Expired_Warm', name: 'Warm Expireds (3-12 Months)', minDays: 91, maxDays: 365 },
    { tier: 'expired_cold_366_730', listingType: 'Expired_Cold', name: 'Cold Expireds (1-2 Years)', minDays: 366, maxDays: 730 }
  ];

  const buckets = {};
  for (const range of tierDateRanges) {
    buckets[range.tier] = { records: [], leads: [] };
  }

  let outsideRange = 0;
  let noDateCount = 0;

  for (let i = 0; i < jsonRecords.length; i++) {
    const propData = leadData[i]?.propertyData || {};
    const listing = propData.listing || {};
    const failedDate = listing.failedListingDate || listing.originalListingDate || null;

    let daysSinceExpired = -1;
    if (failedDate) {
      const expDate = new Date(failedDate);
      daysSinceExpired = Math.floor((now - expDate) / (1000 * 60 * 60 * 24));
    } else {
      noDateCount++;
      daysSinceExpired = 200;
    }

    let assigned = false;
    for (const range of tierDateRanges) {
      if (daysSinceExpired >= range.minDays && daysSinceExpired <= range.maxDays) {
        buckets[range.tier].records.push(jsonRecords[i]);
        const enrichedLead = JSON.parse(JSON.stringify(leadData[i]));
        enrichedLead.propertyData.listingExpiredDate = failedDate;
        enrichedLead.propertyData.daysSinceExpired = daysSinceExpired;
        enrichedLead.propertyData.expiredTier = range.tier;
        enrichedLead.propertyData.campaignType = 'expired';
        if (range.tier === 'expired_hot_0_90') enrichedLead.propertyData.distressScore += 15;
        else if (range.tier === 'expired_warm_91_365') enrichedLead.propertyData.distressScore += 10;
        else enrichedLead.propertyData.distressScore += 5;
        buckets[range.tier].leads.push(enrichedLead);
        assigned = true;
        break;
      }
    }

    if (!assigned) {
      outsideRange++;
      console.log('SKIP: Expired ' + daysSinceExpired + ' days ago (outside 0-730)');
    }
  }

  console.log('=== EXPIRED DATE SPLIT ===');
  for (const range of tierDateRanges) {
    const tc = tierInfo.expiredTierConfigs.find(function(c) { return c.tier === range.tier; }) || {};
    console.log('  ' + range.tier + ': ' + buckets[range.tier].records.length + ' records (target: ' + (tc.leadsTarget || '?') + ')');
  }
  if (noDateCount > 0) console.log('  No date (defaulted to warm): ' + noDateCount);
  if (outsideRange > 0) console.log('  Outside 0-730 range: ' + outsideRange);

  const results = [];
  for (const range of tierDateRanges) {
    const bucket = buckets[range.tier];
    if (bucket.records.length > 0) {
      const tc = tierInfo.expiredTierConfigs.find(function(c) { return c.tier === range.tier; }) || {};
      results.push({
        json: {
          hasLeads: true,
          tier: range.tier,
          tierName: tc.name || range.name,
          listingType: range.listingType,
          importId: tierInfo.importId,
          importDate: tierInfo.importDate,
          leadsCount: bucket.records.length,
          originalBatchDataCount: originalBatchDataCount,
          jsonData: bucket.records,
          leadData: bucket.leads,
          deduplicationStats: deduplicationStats,
          campaignType: 'expired',
          validationStats: {
            totalRecords: properties.length,
            emptyAddresses: emptyAddressCount,
            invalidCityState: invalidAddressCount,
            noMailingAddress: noMailingCount,
            noMailingZip: noMailingZipCount,
            poBoxFiltered: poBoxCount,
            commercialFiltered: commercialCount,
            batchdataInvalid: batchdataInvalidCount,
            validRecords: bucket.records.length,
            creditsSaved: creditsSaved
          },
          distressInfo: { indicators: ['expired_listing'], score: tierDistressScore }
        }
      });
    }
  }

  if (results.length === 0) {
    return [{ json: { 
      hasLeads: false, tier: 'expired_combined', tierName: 'All Expired Listings',
      listingType: 'Expired', importId: tierInfo.importId, importDate: tierInfo.importDate, 
      leadsCount: 0, originalBatchDataCount: originalBatchDataCount, jsonData: null, leadData: []
    } }];
  }

  return results;
}

// === EXISTING RETURN (NON-EXPIRED TIERS — UNCHANGED) ===
console.log('=== ADDRESS SWAP APPLIED ===');
console.log('Tracerfy PRIMARY address = mailing (where owner lives)');
console.log('Tracerfy SECONDARY address = property (investment)');

return [{ json: {
  hasLeads: true,
  tier: tierInfo.tier,
  tierName: tierInfo.tierName,
  listingType: tierInfo.listingType,
  importId: tierInfo.importId,
  importDate: tierInfo.importDate,
  leadsCount: validLeadCount,
  originalBatchDataCount: originalBatchDataCount,
  jsonData: jsonRecords,
  leadData: leadData,
  deduplicationStats: deduplicationStats,
  validationStats: {
    totalRecords: properties.length,
    emptyAddresses: emptyAddressCount,
    invalidCityState: invalidAddressCount,
    noMailingAddress: noMailingCount,
    noMailingZip: noMailingZipCount,
    poBoxFiltered: poBoxCount,
    commercialFiltered: commercialCount,
    batchdataInvalid: batchdataInvalidCount,
    validRecords: validLeadCount,
    creditsSaved: creditsSaved,
    qualityGrades: { A: gradeA, B: gradeB, C: gradeC }
  },
  distressInfo: {
    indicators: tierDistressIndicators,
    score: tierDistressScore
  }
} }];

const jsonData = $('Build JSON Data for Tracerfy').first().json;
const tracerfyResponse = $('Upload CSV to Tracerfy').first().json;
const convexResponse = $input.first().json;
const staticData = $getWorkflowStaticData('global');
if (!staticData.tierResults) staticData.tierResults = [];

const result = {
  tier: jsonData.tier,
  tierName: jsonData.tierName,
  listingType: jsonData.listingType,
  importId: jsonData.importId,
  leadsSubmitted: jsonData.leadsCount,
  jobId: tracerfyResponse.queue_id || tracerfyResponse.job_id || tracerfyResponse.id || 'unknown',
  convexJobId: convexResponse.jobId || convexResponse.id || 'unknown',
  status: 'submitted_to_tracerfy',
  success: true,
  async: true
};

staticData.tierResults.push(result);
console.log(`Tier ${jsonData.tier}: Submitted ${jsonData.leadsCount} leads to Tracerfy, jobId: ${result.jobId}`);

return [{ json: result }];

// NO-LEADS PATH: Do NOT advance pagination when BatchData returns 0 results.
// Previously this called pagination-update which advanced the skip counter,
// causing the workflow to skip past all available leads permanently.
// Now we just log and move to the next tier.

const tierData = $('Build BatchData Request').first().json;
const batchDataResponse = $('Call BatchData API').first().json;

const resultsFound = (batchDataResponse.results && batchDataResponse.results.meta && batchDataResponse.results.meta.results) 
  ? batchDataResponse.results.meta.results.resultsFound 
  : 0;

console.log(`Tier ${tierData.tier}: 0 results returned. Pagination NOT advanced (will retry same offset next run).`);
console.log(`BatchData meta: resultsFound=${resultsFound}`);

return [{ json: { 
  tier: tierData.tier, 
  action: 'pagination_skipped', 
  reason: 'no_results_returned',
  resultsFound: resultsFound
} }];

// Handle no leads from BatchData API (0 results)
const tierData = $('Build BatchData Request').first().json;
const batchDataResponse = $('Call BatchData API').first().json;
const staticData = $getWorkflowStaticData('global');
if (!staticData.tierResults) staticData.tierResults = [];

// Get results found from BatchData response
const resultsFound = (batchDataResponse.results && batchDataResponse.results.meta && batchDataResponse.results.meta.results) 
  ? batchDataResponse.results.meta.results.resultsFound 
  : 0;
const resultCount = (batchDataResponse.results && batchDataResponse.results.properties) 
  ? batchDataResponse.results.properties.length 
  : 0;

const result = {
  tier: tierData.tier,
  tierName: tierData.tierName,
  listingType: tierData.listingType,
  importId: tierData.importId,
  leadsSubmitted: 0,
  resultsFound: resultsFound,
  resultCount: resultCount,
  status: resultCount === 0 ? 'no_results_from_batchdata' : 'no_leads_after_filtering',
  success: false,
  async: false
};

staticData.tierResults.push(result);
console.log(`Tier ${tierData.tier}: No leads - BatchData returned ${resultCount} results (${resultsFound} found)`);

return [{ json: result }];

// Get all tier results from static data
const staticData = $getWorkflowStaticData('global');
const allResults = staticData.tierResults || [];

// Clear for next run
staticData.tierResults = [];

// Calculate totals
let totalLeadsSubmitted = 0;
let totalJobsCreated = 0;
let tiersWithNoLeads = 0;

const tiers = {};
const jobs = [];

for (const result of allResults) {
  if (result.tier) {
    tiers[result.tier] = {
      name: result.tierName,
      listingType: result.listingType,
      leadsSubmitted: result.leadsSubmitted || 0,
      jobId: result.jobId || null,
      status: result.status,
      success: result.success
    };

    totalLeadsSubmitted += result.leadsSubmitted || 0;

    if (result.success && result.jobId) {
      totalJobsCreated++;
      jobs.push({
        tier: result.tier,
        jobId: result.jobId,
        leadsSubmitted: result.leadsSubmitted
      });
    } else {
      tiersWithNoLeads++;
    }
  }
}

const summary = {
  importId: allResults[0]?.importId || 'import_' + Date.now(),
  importDate: new Date().toISOString().split('T')[0],
  source: 'tracerfy_async',
  tiers: tiers,
  // FIXED: Match Convex createImportLog schema EXACTLY
  // Only include fields that are in the validator
  totals: {
    leadsTarget: totalLeadsSubmitted,
    leadsReceived: totalLeadsSubmitted,
    leadsStaged: 0
  },
  // Store extra info outside totals for Slack report
  meta: {
    tiersProcessed: allResults.length,
    jobsCreated: totalJobsCreated,
    tiersWithNoLeads: tiersWithNoLeads
  },
  jobs: jobs,
  status: 'jobs_submitted'
};

console.log('=== ASYNC IMPORT SUMMARY ===');
console.log(`Tiers: ${allResults.length}, Leads: ${totalLeadsSubmitted}, Jobs: ${totalJobsCreated}`);

return [{ json: summary }];

